using System.Collections;
using Astronomy.MediaFactory.Infrastructure.Production.Narration.Semantics.Resolution.V1.Contracts;
using Astronomy.MediaFactory.Infrastructure.Production.Narration.Semantics.Sources.Adapters.Contracts;
namespace Astronomy.MediaFactory.Infrastructure.Production.Narration.Semantics.Resolution.V1.Evaluation;
public interface ISemanticConflictAnalyzerV1 { SemanticConflictSetV1 Analyze(IEnumerable<SemanticSourceCandidateV1> candidates); }
public sealed class SemanticConflictAnalyzerV1 : ISemanticConflictAnalyzerV1
{ public SemanticConflictSetV1 Analyze(IEnumerable<SemanticSourceCandidateV1> candidates){var c=candidates.OrderBy(x=>Id(x),StringComparer.Ordinal).ToArray(); if(c.Length==0)return new(default!,[]); var conflicts=new List<SemanticConflictV1>(); for(int i=0;i<c.Length;i++)for(int j=i+1;j<c.Length;j++){var a=c[i];var b=c[j];var status=Compare(a.TypedValue.Value,b.TypedValue.Value);bool material=status is SemanticConflictStatusV1.MaterialDisagreement or SemanticConflictStatusV1.IncompatibleValueTypes;bool resolvable=status is SemanticConflictStatusV1.Complementary or SemanticConflictStatusV1.EquivalentNormalized or SemanticConflictStatusV1.UnitNormalizableAgreement or SemanticConflictStatusV1.Agreement;if(a.SourceId==b.SourceId)status=SemanticConflictStatusV1.SameSourceDuplicate;if(a.Provenance.Select(p=>p.SourcePropertyPath).Intersect(b.Provenance.Select(p=>p.SourcePropertyPath),StringComparer.Ordinal).Any())status=SemanticConflictStatusV1.ProvenanceDuplicate;conflicts.Add(new($"conflict-{i}-{j}",a.CapabilityId,[Id(a),Id(b)],status,material,!material||resolvable,status.ToString(),status.ToString(),$"{status} between candidates."));} return new(c[0].CapabilityId,conflicts);}
 static string Id(SemanticSourceCandidateV1 c)=>$"{c.AdapterId}|{c.SourceId}|{c.CanonicalValue}";
 static SemanticConflictStatusV1 Compare(object? a, object? b){ if(a is null||b is null)return Equals(a,b)?SemanticConflictStatusV1.Agreement:SemanticConflictStatusV1.MaterialDisagreement; if(a.GetType()!=b.GetType())return SemanticConflictStatusV1.IncompatibleValueTypes; if(Normal(a)==Normal(b))return SemanticConflictStatusV1.EquivalentNormalized; if(a is AngularSeparationValue aa&&b is AngularSeparationValue ab)return Math.Abs(ToDeg(aa)-ToDeg(ab))<0.0001m?SemanticConflictStatusV1.UnitNormalizableAgreement:SemanticConflictStatusV1.MaterialDisagreement; if(a is ObservationLocationValue la&&b is ObservationLocationValue lb)return la.Latitude==lb.Latitude&&la.Longitude==lb.Longitude?SemanticConflictStatusV1.Agreement:SemanticConflictStatusV1.MaterialDisagreement; if(a is MeteorActivityValue ma&&b is MeteorActivityValue mb){if(ma.Zhr.HasValue&&mb.Zhr.HasValue&&ma.Zhr!=mb.Zhr)return SemanticConflictStatusV1.MaterialDisagreement;return SemanticConflictStatusV1.Complementary;} if(a is EclipseCircumstancesValue ea&&b is EclipseCircumstancesValue eb)return !string.Equals(ea.SolarOrLunarClassification,eb.SolarOrLunarClassification,StringComparison.OrdinalIgnoreCase)?SemanticConflictStatusV1.MaterialDisagreement:SemanticConflictStatusV1.Agreement; if(a is SafetyGuidanceValue sa&&b is SafetyGuidanceValue sb)return sa.DirectSolarViewing!=sb.DirectSolarViewing||!string.Equals(sa.Guidance,sb.Guidance,StringComparison.OrdinalIgnoreCase)?SemanticConflictStatusV1.MaterialDisagreement:SemanticConflictStatusV1.Agreement; return SemanticConflictStatusV1.MaterialDisagreement; }
 static decimal ToDeg(AngularSeparationValue v)=>v.Degrees+(v.Arcminutes??0)/60m+(v.Arcseconds??0)/3600m;
 static string Normal(object v){ if(v is EventWindowValue e)return $"{e.StartUtc?.ToUniversalTime():O}|{e.PeakUtc?.ToUniversalTime():O}|{e.EndUtc?.ToUniversalTime():O}"; if(v is IEnumerable<AstronomicalObjectValue> objs)return string.Join('|',objs.Select(o=>o.Name.ToUpperInvariant()).Order()); return v.ToString()??""; }
}
